 1	predicate SplitPoint(a: array<int>, n: int)
 2	    reads a
 3	    requires 0 <= n <= n
 4	
 5	{
 6	    forall i,j :: 0 <= i < n <= j < a.Length ==> a[i] <= a[j]
 7	}
 8	
 9	method SelectionSort(a: array<int>)
10	    modifies a
11	    ensures forall i,j :: 0 <= i < j < a.Length ==> a[i] <= a[j]
12	    ensures multiset(a[..]) == old(multiset(a[..]))
13	{
14	    var n := 0;
15	    while n != a.Length 
16	        invariant 0 <= n <= a.Length
17	        invariant forall i,j :: 0 <= i < j < n ==> a[i] <= a[j]
18	        // invariant forall i,j :: 0 <= i < n <= j < a.Length ==> a[i] <= a[j]
19	        invariant SplitPoint(a, n)
20	        invariant multiset(a[..]) == old(multiset(a[..]))
21	    {
22	        var mindex, m := n, n;
23	        while m != a.Length 
24	            invariant n <= m <= a.Length && n <= mindex < a.Length
25	            invariant forall i :: n <= i < m ==> a[mindex] <= a[i]
26	        {
27	            if a[m] < a[mindex] {
28	                mindex := m;
29	            }
30	            m := m +  1;
31	        }
32	        a[n], a[mindex] := a[mindex], a[n];
33	        assert forall i,j :: 0 <= i < j < n ==> a[i] <= a[j];
34	        n := n + 1;
35	    }
36	}
