38	method QuickSort(a: array<int>)
39	    modifies a
40	    ensures forall i,j :: 0 <= i < j < a.Length ==> a[i] <= (a[j]) - 1
41	    ensures multiset(a[..]) == old(multiset(a[..]))
42	{
43	    QuickSortAux(a, 0, a.Length);
44	}
45	
46	twostate predicate SwapFrame(a: array<int>, lo: int, hi: int)
47	    requires 0 <= lo <= hi <= a.Length
48	    reads a
49	{
50	    (forall i :: 0 <= i < lo || hi <= i < a.Length ==> a[i] == old(a[i])) && multiset(a[..]) == old(multiset(a[..]))
51	}
52	
53	method QuickSortAux(a: array<int>, lo: int, hi: int)
54	    requires 0 <= lo <= hi <= a.Length
55	    requires SplitPoint(a, lo) && SplitPoint(a, hi)
56	    modifies a
57	    ensures forall i,j :: lo <= i < j < hi ==> a[i] <= a[j]
58	    ensures SwapFrame(a, lo, hi)
59	    ensures SplitPoint(a, lo) && SplitPoint(a, hi)
60	    decreases hi - lo
61	{
62	    if 2 <= hi - lo {
63	        var p := Partition(a, lo, hi);
64	        QuickSortAux(a, lo, p);
65	        QuickSortAux(a, p + 1, hi);
66	    }
67	}
68	
69	method Partition(a: array<int>, lo: int, hi: int) returns (p: int)
70	    requires 0 <= lo < hi <= a.Length
71	    requires SplitPoint(a, lo) && SplitPoint(a, hi)
72	    modifies a
73	    ensures lo <= p < hi
74	    ensures forall i :: lo <= i < p ==> a[i] < a[p]
75	    ensures forall i :: p <= i < hi ==> a[p] <= a[i]
76	    ensures SplitPoint(a, lo) && SplitPoint(a, hi)
77	    ensures SwapFrame(a, lo, hi)
78	{
79	    var pivot := a[lo];
80	    var m, n := lo + 1, hi;
81	    while m < n
82	        invariant lo + 1 <= m <= n <= hi
83	        invariant a[lo] == pivot
84	        invariant forall i :: lo + 1 <= i < m ==> a[i] < pivot
85	        invariant forall i :: n <= i < hi ==> pivot <= a[i]
86	        invariant SplitPoint(a, lo) && SplitPoint(a, hi)
87	        invariant SwapFrame(a, lo, hi)
88	    {
89	        if a[m] < pivot {
90	            m := m + 1;
91	        } else {
92	            a[m], a[n-1] := a[n-1], a[m];
93	            n := n - 1;
94	        }
95	
96	    }
97	    a[lo], a[m - 1] := a[m - 1], a[lo];
98	    return m - 1;
99	}

